// Protocol 3: every bundled audio file is accounted for.
//
// A candidate is offline and is given one sample pack. So a bundled audio file
// is one of two things: derived from a recording in the pack, or generated by
// the candidate's own code. IMPLEMENTATION_DETAILS.json says which, file by
// file, and the seal checks the claim instead of taking it:
//
//   - every audio file in the sealed tree (and in the build) is declared;
//   - a file declared as coming from the pack names a recording that is in the
//     pack, and matches it acoustically (bench/lib/run/sample-match.mjs);
//   - a file declared as generated is not a pack recording under another name;
//   - every pack source that was used is credited with its real license.
//
// This module is the declaration half: pure over the stage directory and the
// pack manifest. The acoustic half runs where ffmpeg and the pack are (a box),
// and its results are folded in with applyMatchResults.
import fs from 'node:fs'
import path from 'node:path'
import { NON_ARTIFACT_DIRS, hashFile } from '../shared.mjs'
import { packIndex } from '../sample-pack.mjs'

export const AUDIO_EXTENSIONS = new Set(['.wav', '.flac', '.mp3', '.ogg', '.oga', '.opus', '.m4a', '.aac', '.aif', '.aiff', '.webm', '.caf', '.wma', '.sf2', '.sf3'])
const TEXT_EXTENSIONS = new Set(['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.json', '.html', '.css', '.svg', '.md'])
const SKIPPED_DIRS = new Set([...NON_ARTIFACT_DIRS.filter((name) => name !== 'dist'), 'evidence'])

// A file is audio if its bytes say so, whatever it is called.
export function sniffAudio(buffer) {
  if (buffer.length < 12) return null
  const ascii = (start, length) => buffer.subarray(start, start + length).toString('latin1')
  if (ascii(0, 4) === 'RIFF' && ascii(8, 4) === 'WAVE') return 'wav'
  if (ascii(0, 4) === 'fLaC') return 'flac'
  if (ascii(0, 4) === 'OggS') return 'ogg'
  if (ascii(0, 3) === 'ID3') return 'mp3'
  if (ascii(0, 4) === 'FORM' && ['AIFF', 'AIFC'].includes(ascii(8, 4))) return 'aiff'
  if (ascii(0, 4) === 'caff') return 'caf'
  if (ascii(4, 4) === 'ftyp' && /^(M4A |M4B |mp42|isom|dash)/.test(ascii(8, 4)) && buffer.includes('mp4a')) return 'm4a'
  if (ascii(0, 4) === 'RIFF' && ascii(8, 4) === 'sfbk') return 'sf2'
  return null
}

function head(file, bytes = 4096) {
  const handle = fs.openSync(file, 'r')
  try {
    const buffer = Buffer.alloc(bytes)
    return buffer.subarray(0, fs.readSync(handle, buffer, 0, bytes, 0))
  } finally {
    fs.closeSync(handle)
  }
}

// Every audio file under the stage directory: by extension, or by content for
// anything large enough to be a sample. `inBuild` marks files under dist/.
export function findBundledAudio(stageDir) {
  const files = []
  const visit = (directory, inBuild) => {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const absolute = path.join(directory, entry.name)
      if (entry.isDirectory()) {
        if (!SKIPPED_DIRS.has(entry.name)) visit(absolute, inBuild || (directory === stageDir && entry.name === 'dist'))
        continue
      }
      if (!entry.isFile()) continue
      const extension = path.extname(entry.name).toLowerCase()
      const { size } = fs.statSync(absolute)
      const named = AUDIO_EXTENSIONS.has(extension)
      // Source text is never audio; anything else of sample size is sniffed.
      const kind = named ? extension.slice(1) : (size >= 1024 && !TEXT_EXTENSIONS.has(extension) ? sniffAudio(head(absolute)) : null)
      if (!kind) continue
      files.push({ path: path.relative(stageDir, absolute).split(path.sep).join('/'), bytes: size, sha256: hashFile(absolute), kind, inBuild, disguised: !named })
    }
  }
  visit(stageDir, false)
  return files.sort((a, b) => a.path.localeCompare(b.path))
}

// Source files that embed audio as a data URI. Advisory: such audio is not a
// file the seal can match, so it had better be generated.
export function findInlineAudio(stageDir) {
  const hits = []
  const visit = (directory) => {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const absolute = path.join(directory, entry.name)
      if (entry.isDirectory()) {
        if (!SKIPPED_DIRS.has(entry.name) && entry.name !== 'dist') visit(absolute)
      } else if (entry.isFile() && TEXT_EXTENSIONS.has(path.extname(entry.name).toLowerCase()) && fs.statSync(absolute).size < 32 * 1024 * 1024) {
        if (fs.readFileSync(absolute, 'latin1').includes('data:audio/')) hits.push(path.relative(stageDir, absolute).split(path.sep).join('/'))
      }
    }
  }
  visit(stageDir)
  return hits.sort()
}

const clean = (value) => String(value ?? '').replace(/^\.\//, '').split(path.sep).join('/')

// Check the declarations against the tree and the pack. Returns the problems
// (each one a sentence a candidate can act on), the list of files to match
// acoustically, and a summary for the record.
export function checkSampleProvenance({ stageDir, details, pack }) {
  const problems = []
  const audio = details?.audio ?? {}
  const declared = Array.isArray(audio.files) ? audio.files : []
  if (audio.files !== undefined && !Array.isArray(audio.files)) problems.push('IMPLEMENTATION_DETAILS.json audio.files must be an array')
  const bundled = findBundledAudio(stageDir)
  const index = pack ? packIndex(pack) : null
  const byPath = new Map()
  for (const [position, entry] of declared.entries()) {
    const where = `audio.files[${position}]`
    if (!entry || typeof entry !== 'object' || typeof entry.path !== 'string' || !entry.path.trim()) {
      problems.push(`${where} needs a "path"`)
      continue
    }
    const filePath = clean(entry.path)
    if (byPath.has(filePath)) problems.push(`${where}: ${filePath} is declared twice`)
    if (!['pack', 'generated'].includes(entry.origin)) problems.push(`${where} (${filePath}): "origin" must be "pack" (derived from a recording in inputs/samples/) or "generated" (produced by your own code)`)
    byPath.set(filePath, { ...entry, path: filePath })
  }
  const source = bundled.filter((file) => !file.inBuild)
  const built = bundled.filter((file) => file.inBuild)
  const sourceHashes = new Map(source.map((file) => [file.sha256, file.path]))

  // 1. Nothing bundled goes undeclared.
  const undeclared = source.filter((file) => !byPath.has(file.path))
  if (undeclared.length > 0) {
    problems.push(`${undeclared.length} bundled audio file(s) are not declared in IMPLEMENTATION_DETAILS.json audio.files: ${undeclared.slice(0, 8).map((file) => file.path + (file.disguised ? ` (${file.kind} audio under another extension)` : '')).join(', ')}${undeclared.length > 8 ? ', …' : ''}. Every audio file needs an entry: {"path", "origin": "pack", "packFile": "<path under inputs/samples/>"} or {"path", "origin": "generated", "description"}`)
  }
  // The build may only contain audio that is in the declared source tree.
  const strays = built.filter((file) => !sourceHashes.has(file.sha256) && !byPath.has(file.path))
  if (strays.length > 0) problems.push(`The build contains ${strays.length} audio file(s) that are not byte-identical to any declared file in the source tree: ${strays.slice(0, 6).map((file) => file.path).join(', ')}. Audio produced at build time must be declared by its dist/ path`)

  // 2. Every declaration points at something real.
  const onDisk = new Map(bundled.map((file) => [file.path, file]))
  const toMatch = []
  const unverifiable = []
  const used = new Map()
  let fromPack = 0
  let generated = 0
  for (const entry of byPath.values()) {
    const file = onDisk.get(entry.path)
    if (!file) {
      problems.push(`audio.files declares ${entry.path}, which is not an audio file in the tree`)
      continue
    }
    const identical = index?.bySha256.get(file.sha256) ?? null
    if (entry.origin === 'generated') {
      generated += 1
      if (typeof entry.description !== 'string' || !entry.description.trim()) problems.push(`${entry.path} is declared "generated" and needs a "description" of what generates it`)
      if (identical) problems.push(`${entry.path} is declared "generated" but is byte-identical to the pack recording ${identical.path}; declare it "origin": "pack" with that "packFile"`)
      continue
    }
    if (entry.origin !== 'pack') continue
    fromPack += 1
    if (!index) {
      problems.push(`${entry.path} is declared as coming from the sample pack, but this run was not given one`)
      continue
    }
    const packFile = clean(entry.packFile)
    const record = index.byPath.get(packFile)
    if (!record || !AUDIO_EXTENSIONS.has(path.extname(packFile).toLowerCase())) {
      problems.push(`${entry.path}: "packFile" ${JSON.stringify(entry.packFile ?? null)} is not a recording in inputs/samples/ (paths are relative to that directory, e.g. "${pack.manifest.files.find((candidate) => candidate.path.endsWith('.flac'))?.path}")`)
      continue
    }
    if (identical && identical.path !== packFile) problems.push(`${entry.path} is a byte-for-byte copy of ${identical.path}, not of the declared ${packFile}`)
    used.set(record.source, (used.get(record.source) ?? 0) + 1)
    if (entry.verifiable === false) {
      if (typeof entry.reason !== 'string' || !entry.reason.trim()) problems.push(`${entry.path} is marked "verifiable": false and needs a "reason" (what was done to the recording that changes its pitch or timing)`)
      unverifiable.push({ path: entry.path, packFile, reason: entry.reason ?? null })
    } else {
      toMatch.push({ path: entry.path, packFile })
    }
  }

  // 3. Every source that was used is credited, with the license it really has.
  const credited = new Map((Array.isArray(audio.sampleSources) ? audio.sampleSources : []).filter((entry) => entry && typeof entry.id === 'string').map((entry) => [entry.id, entry]))
  const sources = {}
  for (const [sourceId, count] of used) {
    const record = index.sources.get(sourceId)
    sources[sourceId] = { name: record.name, license: record.license, files: count }
    const credit = credited.get(sourceId)
    if (!credit) problems.push(`Samples from "${record.name}" are bundled, but audio.sampleSources has no entry with "id": "${sourceId}". Copy its entry from inputs/samples/sample-sources.json`)
    else if (credit.license !== record.license) problems.push(`audio.sampleSources entry "${sourceId}" gives its license as ${JSON.stringify(credit.license)}; the pack says ${record.license}. Copy the entry from inputs/samples/sample-sources.json`)
  }

  return {
    version: 1,
    pack: pack ? { id: pack.id, version: pack.version, manifestSha256: pack.digest } : null,
    bundled: source.length,
    bundledBytes: source.reduce((total, file) => total + file.bytes, 0),
    declared: byPath.size,
    fromPack,
    generated,
    sources,
    unverifiable,
    inlineAudio: findInlineAudio(stageDir),
    acoustic: null,
    problems,
    toMatch,
  }
}

// Fold the acoustic results in: a file that does not match the recording it
// names is a problem, and the message says what to do about it.
export function applyMatchResults(report, match) {
  const failures = (match?.results ?? []).filter((result) => result.status !== 'match')
  const scores = (match?.results ?? []).filter((result) => result.status === 'match').map((result) => result.score)
  report.acoustic = {
    checked: match?.results?.length ?? 0,
    matched: scores.length,
    threshold: match?.threshold ?? null,
    lowestMatch: scores.length ? Math.min(...scores) : null,
    failed: failures.map(({ path: file, packFile, status, score }) => ({ path: file, packFile, status, score })),
  }
  if (failures.length > 0) {
    report.problems.push(`${failures.length} bundled sample(s) do not match the pack recording they are declared to come from: ${failures.slice(0, 6).map((result) => `${result.path} ⇐ ${result.packFile} (${result.status}${result.status === 'mismatch' ? `, similarity ${result.score}` : ''})`).join('; ')}${failures.length > 6 ? '; …' : ''}. A sample matches when it is a cut of the recording (trimmed, faded, levelled, channel-mixed, resampled, re-encoded). Name the recording each file really came from; if a file was pitch-shifted, time-stretched, or layered from recordings, add "verifiable": false and a "reason"; if your code synthesized it, declare it "origin": "generated"`)
  }
  return report
}

// The evidence entries the seal records. Blocking under protocol 3.
export function sampleProvenanceEvidence(report, { blocking = true } = {}) {
  const id = 'sample provenance'
  const entries = []
  if (report.problems.length > 0) {
    entries.push({ id, ...(blocking ? {} : { advisory: true }), passed: false, detail: report.problems.join(' | ') })
  } else if (report.bundled === 0) {
    entries.push({ id, ...(blocking ? {} : { advisory: true }), passed: true, detail: 'No bundled audio files: every sound is generated at run time' })
  } else {
    const credits = Object.entries(report.sources).map(([source, record]) => `${record.files} from ${source} (${record.license})`).join(', ')
    entries.push({
      id,
      ...(blocking ? {} : { advisory: true }),
      passed: true,
      detail: `${report.bundled} bundled audio files, all declared: ${report.fromPack} from the sample pack${credits ? ` — ${credits}` : ''}; ${report.generated} generated${report.acoustic ? `. ${report.acoustic.matched} of ${report.acoustic.checked} pack-derived files match the recording they name (lowest similarity ${report.acoustic.lowestMatch ?? 'n/a'})` : ''}`,
    })
  }
  if (report.unverifiable.length > 0) {
    entries.push({ id: 'sample provenance: unverified derivations', advisory: true, passed: false, detail: `${report.unverifiable.length} file(s) are declared as derived from pack recordings in ways the seal cannot match acoustically: ${report.unverifiable.slice(0, 5).map((entry) => `${entry.path} ⇐ ${entry.packFile} (${entry.reason})`).join('; ')}` })
  }
  if (report.inlineAudio.length > 0) {
    entries.push({ id: 'sample provenance: inline audio', advisory: true, passed: false, detail: `Audio is embedded as data: URIs in ${report.inlineAudio.slice(0, 5).join(', ')}. It is not a file the seal can match, so it must be generated` })
  }
  return entries
}
